# =================================================================
# ARCHIVO GENERADO AUTOMÁTICAMENTE A PARTIR DE LA DEFINICIÓN: layers.02_tematico_pobreza_coneval 
# Indice de Pobreza del CONEVAL en munucipios de Veracruz 
# =================================================================


# Capa: Menor al 50%
LAYER
  NAME "c_pobreza_0"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, porcentaje FROM coneval.indice_pobreza WHERE porcentaje<50) AS t1 USING UNIQUE gid USING SRID=900913"

  METADATA
    "wms_title" "Menor al 50%"
    "wms_enable_request" "*"
  END

  CLASS
    NAME "Menor al 50%"
    STYLE
      COLOR 255 255 255
      OPACITY 60
      OUTLINECOLOR 60 60 60
      WIDTH 0.8
    END
  END
END
  
